import{_ as a,c as n,o as p,ag as i}from"./chunks/framework.D4Vqf8I7.js";const h=JSON.parse('{"title":"Open Brodcast Software","description":"","frontmatter":{},"headers":[],"relativePath":"docs/wi/obs.md","filePath":"docs/wi/obs.md","lastUpdated":1787306919000}'),e={name:"docs/wi/obs.md"};function l(t,s,r,o,c,d){return p(),n("div",null,s[0]||(s[0]=[i(`<h1 id="open-brodcast-software" tabindex="-1">Open Brodcast Software <a class="header-anchor" href="#open-brodcast-software" aria-label="Permalink to &quot;Open Brodcast Software&quot;">​</a></h1><p><img src="https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/1905180/ss_aefa14f73426de7ae6be79876b1a8055b11291bc.1920x1080.jpg?t=1733595297" alt=""></p><p>OBS (Open Broadcaster Software) — это бесплатное и открытое программное обеспечение для записи видео и стриминга в реальном времени, широко используемое стримерами, геймерами и контент-мейкерами. Оно позволяет захватывать экран, веб-камеру, микрофон и другие источники, настраивать сцены и переходы, накладывать наложения (overlays), а также транслировать напрямую на платформы вроде YouTube, Twitch или Facebook Live. OBS поддерживает высокое качество записи, гибкие настройки кодеков и работает на Windows, macOS и Linux.</p><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> obs-studio</span></span></code></pre></div><p>или</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flathub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.obsproject.Studio</span></span></code></pre></div><h2 id="для-wayland" tabindex="-1">Для Wayland <a class="header-anchor" href="#для-wayland" aria-label="Permalink to &quot;Для Wayland&quot;">​</a></h2><p>Установите пакеты <code>xdg-desktop-portal</code>, <code>xdg-desktop-portal-wlr</code> и <code>slurp</code>, иначе вы не сможете увидеть опцию захвата экрана или же она не будет работать.</p><h2 id="плагины-если-устанавливали-через-apt-get" tabindex="-1">Плагины (если устанавливали через apt-get) <a class="header-anchor" href="#плагины-если-устанавливали-через-apt-get" aria-label="Permalink to &quot;Плагины (если устанавливали через apt-get)&quot;">​</a></h2><p>obs-vkcapture</p><p>obs-studio-plugin-vaapi</p><p>obs-studio-plugin-droidcam</p><p>obs-studio-plugin-multi-rtmp</p><p>obs-studio-plugin-input-overlay - потыкал его, чёт плохо работает</p><h3 id="сборка-плагина-obs-studio-plugin-rtspserver" tabindex="-1">Сборка плагина obs-studio-plugin-rtspserver <a class="header-anchor" href="#сборка-плагина-obs-studio-plugin-rtspserver" aria-label="Permalink to &quot;Сборка плагина obs-studio-plugin-rtspserver&quot;">​</a></h3><p><a href="https://github.com/iamscottxu/obs-rtspserver" target="_blank" rel="noreferrer">https://github.com/iamscottxu/obs-rtspserver</a></p><div class="warning custom-block"><p class="custom-block-title">Собранный пакет</p><ul><li>obs-studio-plugin-rtspserver-3.1.0: <a href="https://raw.githubusercontent.com/bysnik/wiki/main/rpms/obs-studio-plugin-rtspserver-3.1.0-alt1.x86_64.rpm" target="_blank" rel="noreferrer">obs-studio-plugin-rtspserver-3.1.0-alt1.x86_64.rpm</a></li></ul></div><ol><li>Скачиваем исходники:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/RPM/SOURCES/obs-rtspserver-3.1.0.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/iamscottxu/obs-rtspserver/archive/refs/tags/v3.1.0.tar.gz</span></span></code></pre></div><ol start="2"><li>Создаём спеку:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/RPM/SPECS/obs-studio-plugin-rtspserver.spec</span></span></code></pre></div><details class="details custom-block"><summary>Details</summary><div class="language-spec vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">spec</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%define _unpackaged_files_terminate_build 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name: obs-studio-plugin-rtspserver</span></span>
<span class="line"><span>Version: 3.1.0</span></span>
<span class="line"><span>Release: alt1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Summary: This is a plugin for obs-studio, encode and publish to a RTSP stream.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>License: GPLv2</span></span>
<span class="line"><span>Group: Video</span></span>
<span class="line"><span>Url: https://github.com/iamscottxu/obs-rtspserver</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Source: obs-rtspserver-%version.tar.gz</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BuildRequires(pre): rpm-macros-cmake</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BuildRequires: cmake</span></span>
<span class="line"><span>BuildRequires: gcc-c++</span></span>
<span class="line"><span>BuildRequires: pkgconfig(libobs)</span></span>
<span class="line"><span>BuildRequires: pkgconfig(obs-frontend-api)</span></span>
<span class="line"><span>BuildRequires: pkgconfig(Qt6Core)</span></span>
<span class="line"><span>BuildRequires: pkgconfig(Qt6Widgets)</span></span>
<span class="line"><span>BuildRequires: libb64-devel</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requires: obs-studio</span></span>
<span class="line"><span>Requires: libb64</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExcludeArch: %ix86 %arm %mips</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%description</span></span>
<span class="line"><span>This is a plugin for obs-studio, encode and publish to a RTSP stream.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%prep</span></span>
<span class="line"><span>%setup -n obs-rtspserver-%version</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Фикс заголовков для GCC 13+</span></span>
<span class="line"><span>sed -i &#39;1s/^/#include &lt;cstdlib&gt;\\n/&#39; rtsp-server/net/MemoryManager.cpp</span></span>
<span class="line"><span>sed -i &#39;1s/^/#include &lt;string&gt;\\n/&#39; rtsp_output_helper.h</span></span>
<span class="line"><span>sed -i &#39;8i #include &lt;cstdint&gt;&#39; rtsp-server/xop/media.h</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Обход get_git_version (нет .git в tar-архиве)</span></span>
<span class="line"><span>sed -i &#39;s|get_git_version(OBS_PLUGUN_GIT_TAG OBS_PLUGUIN_VERSION OBS_PLUGUIN_SHORT_VERSION OBS_PLUGUIN_LONG_VERSION)|set(OBS_PLUGUN_GIT_TAG &quot;v%version&quot;)\\nset(OBS_PLUGUIN_VERSION &quot;%version&quot;)\\nset(OBS_PLUGUIN_SHORT_VERSION &quot;%version&quot;)\\nset(OBS_PLUGUIN_LONG_VERSION &quot;%version&quot;)|&#39; CMakeLists.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Убираем -Werror</span></span>
<span class="line"><span>sed -i &#39;s/-Werror//g&#39; external/ObsPluginHelpers.cmake</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Переопределяем путь к заголовкам OBS на системный</span></span>
<span class="line"><span>sed -i &#39;s|set(OBS_FRONTEND_API_INCLUDE_DIRS &quot;\${CMAKE_SOURCE_DIR}/UI/obs-frontend-api&quot;)|set(OBS_FRONTEND_API_INCLUDE_DIRS &quot;%_includedir/obs&quot;)|&#39; CMakeLists.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Используем системный libb64 вместо пустого подмодуля</span></span>
<span class="line"><span>sed -i &#39;s|include_directories(&quot;3rdpart/libb64/libb64/include&quot;)|include_directories(&quot;%_includedir&quot;)|&#39; rtsp-server/CMakeLists.txt</span></span>
<span class="line"><span>sed -i &#39;/add_subdirectory(3rdpart\\/libb64)/d&#39; rtsp-server/CMakeLists.txt</span></span>
<span class="line"><span>sed -i &#39;s|libb64)|b64)|&#39; rtsp-server/CMakeLists.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%build</span></span>
<span class="line"><span>%add_optflags -Wno-reorder</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%cmake \\</span></span>
<span class="line"><span>    -DLIBOBS_INCLUDE_DIR=%_includedir/obs \\</span></span>
<span class="line"><span>    -DLIBOBS_LIB=%_libdir/libobs.so \\</span></span>
<span class="line"><span>    -DOBS_FRONTEND_API_INCLUDE_DIR=%_includedir/obs \\</span></span>
<span class="line"><span>    -DOBS_FRONTEND_API_LIB=%_libdir/libobs-frontend-api.so</span></span>
<span class="line"><span>%cmake_build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%install</span></span>
<span class="line"><span>%cmake_install</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ObsPluginHelpers.cmake ставит файлы в \${CMAKE_SOURCE_DIR}/release.</span></span>
<span class="line"><span># Переносим их в системные пути ALT Linux.</span></span>
<span class="line"><span>mkdir -p %buildroot%_libdir/obs-plugins</span></span>
<span class="line"><span>mkdir -p %buildroot%_datadir/obs/obs-plugins</span></span>
<span class="line"><span></span></span>
<span class="line"><span>install -m 0644 \\</span></span>
<span class="line"><span>    %buildroot%_builddir/obs-rtspserver-%version/release/obs-plugins/64bit/obs-rtspserver.so \\</span></span>
<span class="line"><span>    %buildroot%_libdir/obs-plugins/obs-rtspserver.so</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cp -a \\</span></span>
<span class="line"><span>    %buildroot%_builddir/obs-rtspserver-%version/release/data/obs-plugins/obs-rtspserver \\</span></span>
<span class="line"><span>    %buildroot%_datadir/obs/obs-plugins/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rm -rf %buildroot%_builddir</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%files</span></span>
<span class="line"><span>%doc README.md LICENSE</span></span>
<span class="line"><span>%_libdir/obs-plugins/obs-rtspserver.so</span></span>
<span class="line"><span>%_datadir/obs/obs-plugins/obs-rtspserver</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%changelog</span></span>
<span class="line"><span>* Tue Aug 19 2026 Nikita Bystrov &lt;bystrovno@basealt.ru&gt; 3.1.0-alt1</span></span>
<span class="line"><span>- initial build for ALT</span></span></code></pre></div></details><ol start="3"><li>Устанавливаем сборочные зависимости:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gcc-c++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libobs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> obs-frontend-api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qt6Core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qt6Widgets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libb64-devel</span></span></code></pre></div><ol start="4"><li>Собираем плагин:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rpmbuild</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ba</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/RPM/SPECS/obs-studio-plugi-rtspserver.spec</span></span></code></pre></div>`,27)]))}const b=a(e,[["render",l]]);export{h as __pageData,b as default};
